package com.singtel.redemptionservice;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;import java.math.BigDecimal;import java.time.Instant;import com.singtel.platformcommon.*;
@Service public class RedemptionTransactions{@jakarta.persistence.PersistenceContext private jakarta.persistence.EntityManager entityManager;private final LedgerRepository ledgers;private final RedemptionRepository redemptions;private final Events events;public RedemptionTransactions(LedgerRepository l,RedemptionRepository r,Events e){ledgers=l;redemptions=r;events=e;}
 @Transactional public Redemption redeem(UUID promotionId,String customerId,String key,String actor,String correlation,Map<String,Object> eligibility){var existing=redemptions.findByActorAndIdempotencyKey(actor,key);if(existing.isPresent())return check(existing.get(),promotionId,customerId);if(!Boolean.TRUE.equals(eligibility.get("eligible")))throw DomainError.invalid("INELIGIBLE","Customer does not qualify for this promotion");Map<String,Object> p=(Map<String,Object>)eligibility.get("promotion");Map<String,Object> c=(Map<String,Object>)eligibility.get("customer");if(!Instant.now().isBefore(Instant.parse(p.get("endAt").toString())))throw DomainError.invalid("EXPIRED","Campaign has expired");var ledger=ledgers.lock(promotionId).orElseGet(()->ledgers.saveAndFlush(new CampaignLedger(promotionId)));existing=redemptions.findByActorAndIdempotencyKey(actor,key);if(existing.isPresent())return check(existing.get(),promotionId,customerId);long cap=Long.parseLong(p.get("totalRedemptionLimit").toString());int ownCap=Integer.parseInt(p.get("perCustomerLimit").toString());BigDecimal amount=Money.discount(p.get("discountType").toString(),new BigDecimal(p.get("discountValue").toString()),new BigDecimal(c.get("spend").toString()),p.get("currency").toString());if(ledger.redeemed>=cap||redemptions.countByPromotionIdAndCustomerIdAndStatus(promotionId,customerId,"REDEEMED")>=ownCap||ledger.spent.add(amount).compareTo(new BigDecimal(p.get("budgetLimit").toString()))>0)throw DomainError.conflict("LIMIT_EXHAUSTED","Campaign or customer redemption limit or budget has been reached");var r=new Redemption();r.promotionId=promotionId;r.customerId=customerId;r.idempotencyKey=key;r.actor=actor;r.correlationId=correlation;r.discountAmount=amount;r.currency=p.get("currency").toString();ledger.redeemed++;ledger.spent=ledger.spent.add(amount);ledgers.save(ledger);redemptions.saveAndFlush(r);events.append(r.id.toString(),"redemption.completed",Map.of("redemptionId",r.id,"promotionId",promotionId,"discountAmount",amount,"currency",r.currency));return r;}
 public Redemption check(Redemption r,UUID promotionId,String customerId){if(!r.promotionId.equals(promotionId)||!r.customerId.equals(customerId))throw DomainError.conflict("IDEMPOTENCY_CONFLICT","Idempotency key was used for different request parameters");return r;}
 @Transactional public Redemption cancel(UUID id){Redemption snapshot=redemptions.findById(id).orElseThrow(DomainError::missing);var ledger=ledgers.lock(snapshot.promotionId).orElseThrow(DomainError::missing);entityManager.refresh(snapshot);var r=snapshot;if(r.status.equals("CANCELLED"))return r;r.status="CANCELLED";r.cancelledAt=Instant.now();ledger.redeemed--;ledger.spent=ledger.spent.subtract(r.discountAmount);redemptions.save(r);ledgers.save(ledger);events.append(r.id.toString(),"redemption.cancelled",Map.of("redemptionId",r.id,"promotionId",r.promotionId));return r;}
}
